// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 v) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(v <= address(c).balance);
        uint bal0 = address(this).balance;
        uint256 cnt0;
        try c.depositsCount() returns (uint256 __r) { cnt0 = __r; } catch { return; }
        try c.withdraw(v) {} catch { return; }
        assertTrue(address(this).balance == bal0 + v && c.depositsCount() == cnt0);
    }

    function testFuzz_run(uint256 v) public {
        _run(v);
    }

    receive() external payable {}
}
